import 'dart:convert';

import 'package:yaml/yaml.dart';

import 'entry.dart';

const mediaBlockMarker =
    '<!-- media: generated by Open Timeline, ignored when read -->';

final _idPattern = RegExp(r'^\d{4}[A-Za-z0-9_\-]*$');

bool isValidEntryId(String id) => _idPattern.hasMatch(id);

String entryToMarkdown(Entry e) {
  final b = StringBuffer();
  b.write('---\n');
  b.write('id: ${_q(e.id)}\n');
  b.write('author: ${_q(e.author)}\n');
  b.write('time: ${_q(_formatWithOffset(e.time, e.utcOffsetMinutes))}\n');
  if (e.kind != kindPost) {
    b.write('kind: ${_q(e.kind)}\n');
  }
  if (e.title.isNotEmpty) {
    b.write('title: ${_q(e.title)}\n');
  }
  if (e.series.isNotEmpty) {
    b.write('series: ${_q(e.series)}\n');
  }
  final country = e.country;
  if (country != null && country.isNotEmpty) {
    b.write('country: ${_q(country)}\n');
  }
  if (e.size != sizeMedium) {
    b.write('size: ${_q(e.size)}\n');
  }
  if (e.blend) {
    b.write('blend: true\n');
  }
  if (e.cutout.isNotEmpty) {
    b.write('cutout: ${_q(e.cutout)}\n');
  }
  final color = e.color;
  if (color != null) {
    final rgb = (color & 0xFFFFFF).toRadixString(16).padLeft(6, '0');
    b.write('color: ${_q('#${rgb.toUpperCase()}')}\n');
  }
  final lat = e.lat;
  final lon = e.lon;
  if (lat != null && lon != null && lat.isFinite && lon.isFinite) {
    b.write('location: [${jsonEncode(lat)}, ${jsonEncode(lon)}]\n');
  }
  final place = e.place;
  if (place != null && place.isNotEmpty) {
    b.write('place: ${_q(place)}\n');
  }
  b.write('tags: ${_list(e.tags)}\n');
  b.write('media: ${_list(e.media)}\n');
  b.write('updated: ${_q(e.updated.toUtc().toIso8601String())}\n');
  b.write('deleted: ${e.deleted}\n');
  b.write('conflict: ${e.conflict}\n');
  b.write('---\n');

  final body = _trimRight(
    e.text.replaceAll('\r\n', '\n').replaceAll('\r', '\n'),
  );
  if (body.isNotEmpty) {
    b.write(body);
    b.write('\n');
  }
  if (e.media.isNotEmpty) {
    if (body.isNotEmpty) b.write('\n');
    b.write('$mediaBlockMarker\n');
    for (final name in e.media) {
      final link = Uri.encodeComponent(name);
      if (isImage(name)) {
        b.write('![]($link)\n');
      } else if (isVideo(name)) {
        b.write('[video]($link)\n');
      } else {
        b.write('[file]($link)\n');
      }
    }
  }
  return b.toString();
}

// A JSON string is a valid YAML scalar, but jsonEncode leaves some YAML line breaks and non-printables raw.
int? _parseColor(String? s) {
  final m = RegExp(r'^#?([0-9a-fA-F]{6})$').firstMatch(s?.trim() ?? '');
  return m == null ? null : 0xFF000000 | int.parse(m.group(1)!, radix: 16);
}

String _q(String s) => jsonEncode(s).replaceAllMapped(
  RegExp('[\u007f-\u009f  ﻿]'),
  (m) => '\\u${m[0]!.codeUnitAt(0).toRadixString(16).padLeft(4, '0')}',
);

String _list(List<String> items) => '[${items.map(_q).join(', ')}]';

String _two(int n) => n.toString().padLeft(2, '0');

String _formatWithOffset(DateTime instant, int offsetMinutes) {
  final w = instant.toUtc().add(Duration(minutes: offsetMinutes));
  final b = StringBuffer()
    ..write(w.year.toString().padLeft(4, '0'))
    ..write('-${_two(w.month)}-${_two(w.day)}')
    ..write('T${_two(w.hour)}:${_two(w.minute)}:${_two(w.second)}');
  if (w.microsecond != 0) {
    b.write(
      '.${w.millisecond.toString().padLeft(3, '0')}'
      '${w.microsecond.toString().padLeft(3, '0')}',
    );
  } else if (w.millisecond != 0) {
    b.write('.${w.millisecond.toString().padLeft(3, '0')}');
  }
  if (offsetMinutes == 0) {
    b.write('Z');
  } else {
    final abs = offsetMinutes.abs();
    b.write(
      '${offsetMinutes < 0 ? '-' : '+'}${_two(abs ~/ 60)}:${_two(abs % 60)}',
    );
  }
  return b.toString();
}

Entry entryFromMarkdown(String source, {String? fallbackId}) {
  var s = source;
  if (s.startsWith('﻿')) s = s.substring(1);
  s = s.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
  final lines = s.split('\n');

  var i = 0;
  while (i < lines.length && lines[i].trim().isEmpty) {
    i++;
  }
  if (i >= lines.length || lines[i].trimRight() != '---') {
    throw const FormatException(
      'Missing YAML header (file must start with ---)',
    );
  }
  final headerStart = i + 1;
  var headerEnd = -1;
  for (var j = headerStart; j < lines.length; j++) {
    if (lines[j].trimRight() == '---') {
      headerEnd = j;
      break;
    }
  }
  if (headerEnd < 0) {
    throw const FormatException('Unterminated YAML header (no closing ---)');
  }

  final Object? yaml;
  try {
    yaml = loadYaml(lines.sublist(headerStart, headerEnd).join('\n'));
  } on YamlException catch (e) {
    throw FormatException('Invalid YAML header: ${e.message}');
  }
  if (yaml is! Map) {
    throw const FormatException('YAML header is not a mapping');
  }

  final id = _str(yaml['id']) ?? fallbackId;
  if (id == null || !isValidEntryId(id)) {
    throw FormatException('Missing or invalid id: ${id ?? '(none)'}');
  }

  // Hand-written files may omit the time; the id carries the creation time.
  final timeText = _str(yaml['time']);
  final ({DateTime utc, int offset}) time;
  if (timeText != null) {
    time = _parseTimestamp(timeText);
  } else {
    final m = RegExp(r'^(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})')
        .firstMatch(id);
    if (m == null) throw const FormatException('Missing time');
    time = _parseTimestamp('${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${m[6]}Z');
  }
  final updatedText = _str(yaml['updated']);
  final updated = updatedText == null
      ? time.utc
      : _parseTimestamp(updatedText).utc;

  final loc = _parseLocation(yaml['location']) ?? _parseLatLonKeys(yaml);
  final place = _str(yaml['place']);
  final title = _str(yaml['title'])?.trim() ?? '';
  final color = _parseColor(_str(yaml['color']));
  final kind = _str(yaml['kind'])?.toLowerCase() ?? kindPost;
  final series = _str(yaml['series']) ?? '';
  final country = _str(yaml['country'])?.toUpperCase();
  final sizeText = _str(yaml['size'])?.toLowerCase();
  final size = stampSizes.contains(sizeText) ? sizeText! : sizeMedium;
  final cutout = _str(yaml['cutout'])?.trim() ?? '';

  var bodyLines = lines.sublist(headerEnd + 1);
  final marker = bodyLines.indexWhere((l) => l.trim() == mediaBlockMarker);
  if (marker >= 0) bodyLines = bodyLines.sublist(0, marker);
  final text = _trimRight(
    bodyLines.join('\n').replaceFirst(RegExp(r'^(?:[ \t]*\n)+'), ''),
  );

  return Entry(
    id: id,
    author: _str(yaml['author']) ?? '',
    time: time.utc,
    utcOffsetMinutes: time.offset,
    lat: loc?.$1,
    lon: loc?.$2,
    place: (place == null || place.isEmpty) ? null : place,
    title: title,
    color: color,
    text: text,
    tags: _stringList(yaml['tags'], splitCommas: true),
    media: _stringList(yaml['media'], splitCommas: false),
    updated: updated,
    deleted: _bool(yaml['deleted']),
    conflict: _bool(yaml['conflict']),
    kind: kind,
    series: series,
    country: country,
    size: size,
    blend: _bool(yaml['blend']),
    cutout: cutout,
  );
}

String _trimRight(String s) => s.trimRight();

String? _str(Object? v) {
  if (v == null || v is Map || v is List) return null;
  final s = v.toString().trim();
  return s.isEmpty ? null : s;
}

bool _bool(Object? v) {
  if (v is bool) return v;
  if (v is num) return v != 0;
  if (v is String) {
    return const {
      'true',
      'yes',
      'y',
      'on',
      '1',
    }.contains(v.trim().toLowerCase());
  }
  return false;
}

List<String> _stringList(Object? v, {required bool splitCommas}) {
  if (v == null) return const [];
  final out = <String>[];
  if (v is List) {
    for (final x in v) {
      final s = _str(x);
      if (s != null) out.add(s);
    }
  } else if (v is String) {
    if (splitCommas) {
      for (final part in v.split(',')) {
        final s = part.trim();
        if (s.isNotEmpty) out.add(s);
      }
    } else {
      final s = v.trim();
      if (s.isNotEmpty) out.add(s);
    }
  } else if (v is! Map) {
    out.add(v.toString());
  }
  return out;
}

double? _num(Object? v) {
  final d = v is num
      ? v.toDouble()
      : (v is String ? double.tryParse(v.trim()) : null);
  return (d == null || !d.isFinite) ? null : d;
}

(double, double)? _checkedLatLon(double? lat, double? lon) {
  if (lat == null || lon == null) return null;
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return null;
  return (lat, lon);
}

(double, double)? _parseLocation(Object? v) {
  if (v is List && v.length >= 2) return _checkedLatLon(_num(v[0]), _num(v[1]));
  if (v is String) {
    final parts = v.trim().split(RegExp(r'\s*[,;]\s*|\s+'));
    if (parts.length == 2) {
      return _checkedLatLon(_num(parts[0]), _num(parts[1]));
    }
  }
  return null;
}

(double, double)? _parseLatLonKeys(Map yaml) => _checkedLatLon(
  _num(yaml['lat'] ?? yaml['latitude']),
  _num(yaml['lon'] ?? yaml['lng'] ?? yaml['longitude']),
);

final _timestampPattern = RegExp(
  r'^(\d{4})-(\d{2})-(\d{2})'
  r'(?:[Tt ]\s*(\d{1,2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?\s*([zZ]|[+-]\d{2}(?::?\d{2})?)?)?$',
);

/// Without an offset the clock reading is taken as UTC, independent of the phone's timezone.
({DateTime utc, int offset}) _parseTimestamp(String text) {
  final m = _timestampPattern.firstMatch(text.trim());
  if (m == null) throw FormatException('Invalid timestamp: $text');
  final y = int.parse(m[1]!);
  final mo = int.parse(m[2]!);
  final d = int.parse(m[3]!);
  final h = m[4] == null ? 0 : int.parse(m[4]!);
  final mi = m[5] == null ? 0 : int.parse(m[5]!);
  final sec = m[6] == null ? 0 : int.parse(m[6]!);
  final micros = m[7] == null
      ? 0
      : int.parse(m[7]!.padRight(6, '0').substring(0, 6));

  var offset = 0;
  final o = m[8];
  if (o != null && o.toLowerCase() != 'z') {
    final digits = o.substring(1).replaceAll(':', '');
    final oh = int.parse(digits.substring(0, 2));
    final om = digits.length > 2 ? int.parse(digits.substring(2, 4)) : 0;
    if (om > 59) throw FormatException('Invalid UTC offset: $text');
    offset = (o.startsWith('-') ? -1 : 1) * (oh * 60 + om);
    if (offset.abs() > 18 * 60) {
      throw FormatException('Invalid UTC offset: $text');
    }
  }

  final wall = DateTime.utc(
    y,
    mo,
    d,
    h,
    mi,
    sec,
    micros ~/ 1000,
    micros % 1000,
  );
  if (wall.year != y ||
      wall.month != mo ||
      wall.day != d ||
      wall.hour != h ||
      wall.minute != mi ||
      wall.second != sec) {
    throw FormatException('Invalid date/time: $text');
  }
  return (utc: wall.subtract(Duration(minutes: offset)), offset: offset);
}
